async page => {
  const local = "http://127.0.0.1:18823/Demo_Protype_2/1.1.0/prototype/index.html";
  const target = "https://hw00913-bot.github.io/prototype-demo/index.html";
  const checks = [], layouts = [], errors = [], failedResources = [];
  const onError = e => { if (page.url().startsWith(local)) errors.push(e.message); };
  const onResponse = r => { if (r.url().startsWith("http://127.0.0.1:18823/") && r.status()>=400) failedResources.push({url:r.url(),status:r.status()}); };
  page.on("pageerror",onError); page.on("response",onResponse);
  const snapshot = () => page.evaluate(() => {const s=AppState.get();return {stage:s.authStage,platform:s.loginPlatform,tenantId:s.tenantId,enterpriseId:s.enterpriseId,activeDomain:s.activeDomain,ready:AppState.isReady(),accessValid:AppState.effectiveAccess().valid};});
  const assertStage = async (stage, platform = "") => {
    const s = await snapshot();
    if (s.stage!==stage || s.platform!==platform || (stage!=="READY" && (s.ready||s.tenantId||s.enterpriseId||s.activeDomain||s.accessValid))) throw new Error("Unexpected context: "+JSON.stringify(s));
    return s;
  };
  try {
    await page.reload({waitUntil:"domcontentloaded"}); await page.setViewportSize({width:1440,height:900});
    await page.locator(".current-user-action").click();
    await page.locator("#authUsername").waitFor({state:"visible"});
    if (await page.locator(".auth-platform-switch, [data-login-platform]").count()) throw new Error("Platform entries still visible before credentials");
    await page.screenshot({path:"/private/tmp/cloud-login-order-20261021/01-account.png"});
    checks.push("Account form shows credentials only, with three-step progress");
    await page.locator("#authPassword").fill("wrong");
    await page.getByRole("button",{name:"登录",exact:true}).click();
    await assertStage("ACCOUNT");
    checks.push("Invalid password cannot reach platform or tenant selection");
    await page.locator("#authPassword").fill("123456Aa@");
    await page.getByRole("button",{name:"登录",exact:true}).click();
    await page.getByRole("heading",{name:"选择登录平台",exact:true}).waitFor();
    await assertStage("PLATFORM");
    if(await page.locator("[data-login-platform]").count()!==2)throw new Error("Expected both platform options");
    checks.push("Super-admin password login stops at AI/cloud platform selection without restoring last tenant");
    for(const width of [1440,1920,2560]){
      await page.setViewportSize({width,height:900});
      const layout=await page.evaluate(()=>({width:innerWidth,documentWidth:document.documentElement.scrollWidth,visibleOptions:[...document.querySelectorAll("[data-login-platform]")].filter(x=>{const r=x.getBoundingClientRect();return r.width>0&&r.left>=0&&r.right<=innerWidth;}).length}));
      if(layout.documentWidth>width||layout.visibleOptions!==2)throw new Error("Platform layout failed: "+JSON.stringify(layout));
      layouts.push(layout);
      await page.screenshot({path:"/private/tmp/cloud-login-order-20261021/02-platform-"+width+".png"});
    }
    await page.setViewportSize({width:1440,height:900});
    await page.locator("[data-login-platform=cloud]").click();
    await assertStage("INSTANCE","cloud");
    await page.getByRole("heading",{name:"选择本次管理的租户"}).waitFor();
    await page.reload({waitUntil:"domcontentloaded"});
    await assertStage("INSTANCE","cloud");
    await page.screenshot({path:"/private/tmp/cloud-login-order-20261021/03-cloud-tenant.png"});
    checks.push("Cloud selection reaches tenant picker and reload keeps picker without auto-selecting remembered tenant");
    await page.locator(".auth-choice-row").first().click();
    await page.locator("#platformSwitcher").waitFor({state:"visible"});
    const cloud=await assertStage("READY","cloud");
    if(!cloud.tenantId||!cloud.enterpriseId||!cloud.accessValid)throw new Error("Cloud workspace lacks selected authorized tenant");
    await page.screenshot({path:"/private/tmp/cloud-login-order-20261021/04-cloud-workspace.png"});
    checks.push("Cloud workspace becomes ready only after explicit tenant selection");
    await page.locator("#platformSwitcher").click();
    await page.waitForURL(target,{timeout:20000,waitUntil:"domcontentloaded"});
    checks.push("Authenticated top switch still navigates to exact supplied URL");
    await page.goBack({waitUntil:"domcontentloaded"});
    await page.locator(".current-user-action").click();
    await page.getByRole("tab",{name:"手机号登录"}).click();
    await page.getByRole("button",{name:"登录",exact:true}).click();
    await page.getByRole("heading",{name:"选择登录平台",exact:true}).waitFor();
    await assertStage("PLATFORM");
    checks.push("Mobile authentication also stops at platform selection");
    await page.locator("[data-login-platform=ai]").click();
    await assertStage("INSTANCE","ai");
    if(await page.getByRole("button",{name:"接入配置",exact:true}).count())throw new Error("AI tenant picker exposes cloud setup bypass");
    await page.screenshot({path:"/private/tmp/cloud-login-order-20261021/05-ai-tenant.png"});
    await page.locator(".auth-choice-row").first().click();
    await page.waitForURL(target,{timeout:20000,waitUntil:"domcontentloaded"});
    const destination={url:page.url(),title:await page.title()};
    checks.push("AI selection remains local until tenant click; tenant click navigates to exact supplied URL");
    await page.goBack({waitUntil:"domcontentloaded"});
    await assertStage("INSTANCE","ai");
    await page.getByRole("button",{name:"重新选择平台",exact:true}).click();
    await assertStage("PLATFORM");
    checks.push("Return from AI and choose-platform-back stay unauthenticated to cloud workspace");
    await page.getByRole("button",{name:"返回账号登录",exact:true}).click();
    await page.locator("#authUsername").fill("nissan-admin");
    await page.locator("#authPassword").fill("Abc@123456");
    await page.getByRole("button",{name:"登录",exact:true}).click();
    await assertStage("PLATFORM");
    await page.locator("[data-login-platform=cloud]").click();
    await assertStage("TENANT","cloud");
    const adminTenantCount=await page.locator(".auth-choice-row").count();
    await page.locator(".auth-choice-row").first().click();
    const admin=await assertStage("READY","cloud");
    if(!admin.accessValid)throw new Error("Admin tenant entry invalid");
    checks.push("Tenant administrator also follows account-platform-tenant sequence ("+adminTenantCount+" tenant options)");
    if(errors.length||failedResources.length)throw new Error(JSON.stringify({errors,failedResources}));
    return {checks,layouts,destination,cloud,admin,errors,failedResources};
  }finally{page.off("pageerror",onError);page.off("response",onResponse);}
}

